def prime_factors(n):
    pf = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            pf[d] = pf.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2  # try 2, then odd steps
    if n > 1:
        pf[n] = pf.get(n, 0) + 1
    return pf

def divisors_from_pf(pf):
    # pf: dict prime->exp
    divs = [1]
    for p, e in pf.items():
        # multiply existing by p^k
        mults = [1]
        cur = 1
        for k in range(1, e + 1):
            cur *= p
            mults.append(cur)
        new_divs = []
        for d in divs:
            for m in mults:
                new_divs.append(d * m)
        divs = new_divs
    return divs

